export const OLD_APPS_TELEGRAM_SRC_STYLES_HARDENING_CSS = '/* Telegram WebView constraints only. Component sizing belongs to component styles. */\n\nhtml,\nbody,\n#app,\n.tg-app {\n  max-width: 100%;\n}\n\nhtml,\nbody {\n  overscroll-behavior-x: none;\n}\n\nbody {\n  min-width: 0;\n}\n\n.tg-app {\n  overflow-x: clip;\n  padding-left: max(10px, var(--cribbit-safe-left, 0px));\n  padding-right: max(10px, var(--cribbit-safe-right, 0px));\n}\n\n.tg-room-form,\n.tg-setup-card,\n.tg-grid-2,\n.tg-source-grid,\n.tg-mode-grid,\n.tg-join-row,\n.tg-primary-actions,\n.tg-game-meta,\n.tg-board,\n.tg-player-strip,\n.tg-hand,\n.tg-active-state,\n.tg-wild-picker {\n  min-width: 0;\n}\n\n.tg-input,\n.tg-select,\n.tg-button,\n.tg-mode-card,\n.tg-source-card,\n.tg-count-chip,\n.tg-safety-bar button,\n.tg-wild-picker button,\n.tg-context-sheet button,\n.game-card--tg-hand,\n.game-card--tg-board,\n.tg-deck {\n  touch-action: manipulation;\n}\n\n.tg-input,\n.tg-select,\n.tg-button,\n.tg-mode-card,\n.tg-source-card,\n.tg-count-chip,\n.tg-safety-bar button,\n.tg-wild-picker button {\n  min-height: 44px;\n}\n\n.tg-field-meta,\n.tg-section-label,\n.tg-toggle-row,\n.tg-game-meta,\n.tg-player-chip,\n.tg-context-header,\n.tg-reaction-window {\n  min-width: 0;\n}\n\n.tg-field-meta > *,\n.tg-section-label > *,\n.tg-toggle-row > *,\n.tg-game-meta > *,\n.tg-player-chip > *,\n.tg-context-header > * {\n  min-width: 0;\n}\n\n.tg-field-meta span,\n.tg-section-label small,\n.tg-toggle-row small,\n.tg-player-chip b,\n.tg-player-chip small {\n  overflow-wrap: anywhere;\n}\n\n.tg-player-rail,\n.tg-hand-rail {\n  max-width: 100%;\n  -webkit-overflow-scrolling: touch;\n  overscroll-behavior-inline: contain;\n}\n\n.tg-safety-bar {\n  position: sticky;\n  bottom: max(6px, var(--cribbit-safe-bottom, 0px));\n  z-index: 8;\n  padding: 5px;\n  margin-left: -5px;\n  margin-right: -5px;\n  border: 1px solid rgba(255, 255, 255, .06);\n  border-radius: 12px;\n  background: rgba(5, 6, 10, .92);\n  backdrop-filter: blur(8px);\n}\n\n.tg-context-layer {\n  padding-top: max(8px, var(--cribbit-safe-top, 0px));\n  padding-right: max(10px, var(--cribbit-safe-right, 0px));\n  padding-bottom: max(8px, var(--cribbit-safe-bottom, 0px));\n  padding-left: max(10px, var(--cribbit-safe-left, 0px));\n}\n\n.tg-context-sheet {\n  max-height: min(\n    calc(var(--cribbit-platform-height, 100dvh) - var(--cribbit-safe-top, 0px) - var(--cribbit-safe-bottom, 0px) - 18px),\n    620px\n  );\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  -webkit-overflow-scrolling: touch;\n}\n\n.tg-context-close,\n.tg-color-grid button,\n.tg-answer-grid button,\n.tg-flag-grid button,\n.tg-target-grid button,\n.tg-context-wide {\n  min-height: 44px;\n}\n\n@media (max-height: 620px) {\n  .tg-primary-actions,\n  .tg-safety-bar {\n    position: static;\n  }\n\n  .tg-context-sheet {\n    max-height: calc(var(--cribbit-platform-height, 100dvh) - var(--cribbit-safe-top, 0px) - var(--cribbit-safe-bottom, 0px) - 12px);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tg-switch span,\n  .tg-switch span::after,\n  .game-card--tg-board,\n  .game-card--tg-hand {\n    transition: none;\n  }\n}\n';
